package com.andye.warmod.antiair;import com.andye.warmod.icbm.IcbmFlightControllerManager;import com.andye.warmod.warhead.*;import java.util.*;import net.minecraft.server.level.ServerLevel;public final class StrategicMissileTargetService{private StrategicMissileTargetService(){}public static Optional<StrategicMissileTargetState> state(ServerLevel l,UUID root,long time){var terminal=IncomingWarheadRegistry.get(l,root);if(terminal.isPresent()){var e=terminal.get();return Optional.of(new StrategicMissileTargetState(root,e.payloadType(),e.position(),e.getDeltaMovement(),true,true));}return IcbmFlightControllerManager.targetState(l,root,time);}}